(()=>{const root=document.querySelector('[data-pet-dashboard]');if(!root)return;const sprite=root.querySelector('[data-pet-dashboard-sprite]');const label=root.querySelector('[data-pet-dashboard-state]');const buttons=[...root.querySelectorAll('[data-pet-dashboard-set]')];const states={idle:{row:0,frames:6,fps:5},greeting:{row:3,frames:4,fps:6},fraggle:{row:3,frames:4,fps:6},heart:{row:0,frames:6,fps:5},music:{row:4,frames:5,fps:8},thinking:{row:8,frames:6,fps:5},glitch:{row:5,frames:8,fps:8},playful:{row:4,frames:5,fps:8}};let timer=null,frame=0;function setState(name){const cfg=states[name]||states.idle;frame=0;clearInterval(timer);label.textContent=name.toUpperCase();buttons.forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.petDashboardSet===name)));draw(cfg);timer=setInterval(()=>{frame=(frame+1)%cfg.frames;draw(cfg)},1000/cfg.fps)}function draw(cfg){sprite.style.backgroundPosition='-'+(frame*192)+'px -'+(cfg.row*208)+'px'}buttons.forEach(b=>b.addEventListener('click',()=>setState(b.dataset.petDashboardSet)));setState('idle')})();